<template>
<div class="container-fluid my-4">
    <!-- Header -->
    <div class="d-flex justify-content-between align-items-center mb-3">
      <div>
        <p class="text-uppercase text-primary small mb-1">Content Management</p>
        <h1 class="h3 mb-0">Pages</h1>
      </div>
      <button class="btn btn-primary" @click="openCreate">+ New Page</button>
    </div>

    <!-- Alert -->
    <div v-if="alert.show" :class="['alert', alert.type === 'error' ? 'alert-danger' : 'alert-success']">
      {{ alert.message }}
    </div>

    <!-- Table -->
    <div v-if="loading" class="text-center py-5">Loading…</div>
    <div v-else-if="!filteredPages.length" class="text-center py-5">No pages found.</div>
    <div v-else class="table-responsive">
      <table class="table table-hover align-middle">
        <thead class="table-light text-uppercase small">
          <tr>
            <th></th>
            <th>#</th>
            <th>Title</th>
            <th>Slug</th>
            <th>Status</th>
            <th>Sections</th>
            <th>Media</th>
            <th>Created</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody v-for="p in filteredPages" :key="p.id">
          <!-- Main row -->
          <tr>
            <td>
              <button class="btn btn-sm btn-outline-secondary" @click="toggleExpand(p.id)">
                {{ expandedId === p.id ? '-' : '+' }}
              </button>
            </td>
            <td>{{ p.id }}</td>
            <td>{{ p.title }}</td>
            <td><code>{{ p.slug }}</code></td>
            <td>
              <span :class="['badge', p.status === 'published' ? 'bg-success' : p.status === 'draft' ? 'bg-warning text-dark' : 'bg-secondary']">
                {{ p.status }}
              </span>
            </td>
            <td>{{ p.sections?.length ?? 0 }}</td>
            <td>{{ p.media?.length ?? 0 }}</td>
            <td>{{ formatDate(p.created_at) }}</td>
            <td>
              <button class="btn btn-sm btn-outline-primary me-1" @click="openEdit(p)">✏️</button>
              <button class="btn btn-sm btn-outline-danger" @click="confirmDelete(p)">🗑️</button>
            </td>
          </tr>

          <!-- Expand row -->
<tr v-if="expandedId === p.id">
  <td colspan="9">
    <div class="row g-3">

      <!-- Sections -->
      <div class="col-md-2">
        <h6>Sections ({{ p.sections?.length ?? 0 }})</h6>
        <ul class="list-group list-group-flush">
          <li
            v-for="s in p.sections"
            :key="s.id"
            class="list-group-item d-flex justify-content-between align-items-center"
          >
            <span>{{ s.type }}</span>
            <span v-if="s.children?.length" class="badge bg-primary rounded-pill">{{ s.children.length }}</span>
          </li>
        </ul>
      </div>

      <!-- Media -->
      <div class="col-md-10">
        <h6>Media ({{ p.media?.length ?? 0 }})</h6>
        <ul class="list-group list-group-flush">
          <li
            v-for="m in p.media"
            :key="m.id"
            class="list-group-item p-0"
          >
            <a
              :href="mediaUrl(m.file_path)"
              target="_blank"
              class="d-flex align-items-center gap-2 p-2 text-decoration-none text-dark"
              style="width: 100%;"
            >
              <template v-if="m.type === 'image'">
                <img :src="mediaUrl(m.file_path)" alt="" class="img-thumbnail" style="width:36px; height:36px;" />
              </template>
              <template v-else>
                📄
              </template>

              <span class="text-truncate" style="max-width: calc(100% - 100px);" :title="m.file_path.split('/').pop()">
                {{ m.file_path.split('/').pop() }}
              </span>

              <span class="badge bg-secondary ms-auto">{{ m.type }}</span>
            </a>
          </li>
        </ul>
      </div>

    </div>
  </td>
</tr>
        </tbody>
      </table>
    </div>

    <!-- Modal -->
    <div class="modal fade" :class="{ show: modal.show }" style="display: block;" tabindex="-1" v-if="modal.show">
      <div class="modal-dialog">
        <div class="modal-content">
          <div class="modal-header">
            <h5 class="modal-title">{{ modal.mode === 'create' ? 'New Page' : 'Edit Page' }}</h5>
            <button type="button" class="btn-close" @click="closeModal"></button>
          </div>
          <div class="modal-body">
            <div class="mb-3">
              <label class="form-label">Title</label>
              <input v-model="form.title" class="form-control" @input="autoSlug" />
            </div>
            <div class="mb-3">
              <label class="form-label">Slug</label>
              <input v-model="form.slug" class="form-control" />
            </div>
            <div class="mb-3">
              <label class="form-label">Status</label>
              <select v-model="form.status" class="form-select">
                <option value="published">Published</option>
                <option value="draft">Draft</option>
                <option value="archived">Archived</option>
              </select>
            </div>
          </div>
          <div class="modal-footer">
            <button class="btn btn-secondary" @click="closeModal">Cancel</button>
            <button class="btn btn-primary" @click="submitForm">{{ modal.mode === 'create' ? 'Create' : 'Save' }}</button>
          </div>
        </div>
      </div>
    </div>

  </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue'
import axios from 'axios'

const APP_URL = 'https://bushman.ink'
const api = axios.create({ baseURL: `${APP_URL}/api/v2/` })

// ── State ─────────────────────────────────────────────────────────────────────
const pages        = ref([])
const loading      = ref(true)
const saving       = ref(false)
const search       = ref('')
const expandedId   = ref(null)
const deleteTarget = ref(null)

const modal  = ref({ show: false, mode: 'create' })
const form   = ref({ id: null, title: '', slug: '', status: 'published' })
const errors = ref({})
const alert  = ref({ show: false, type: 'success', message: '' })
let alertTimer = null

// ── Computed ──────────────────────────────────────────────────────────────────
const filteredPages = computed(() => {
  const q = search.value.toLowerCase()
  return pages.value.filter(p =>
    p.title.toLowerCase().includes(q) || p.slug.toLowerCase().includes(q)
  )
})

// ── Helpers ───────────────────────────────────────────────────────────────────
const formatDate = (iso) =>
  new Date(iso).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })

const mediaUrl = (path) => {
  if (!path) return ''
  return /^https?:\/\//i.test(path) ? path : `${APP_URL}/${path}`
}

const autoSlug = () => {
  if (modal.value.mode === 'create') {
    form.value.slug = form.value.title
      .toLowerCase().trim()
      .replace(/[^a-z0-9\s-]/g, '')
      .replace(/\s+/g, '-')
  }
}

const showAlert = (message, type = 'success') => {
  clearTimeout(alertTimer)
  alert.value = { show: true, type, message }
  alertTimer = setTimeout(() => (alert.value.show = false), 3500)
}

const validate = () => {
  const e = {}
  if (!form.value.title.trim()) e.title = 'Title is required.'
  if (!form.value.slug.trim())  e.slug  = 'Slug is required.'
  errors.value = e
  return !Object.keys(e).length
}

const toggleExpand = (id) => {
  expandedId.value = expandedId.value === id ? null : id
}

// ── CRUD ──────────────────────────────────────────────────────────────────────
const fetchPages = async () => {
  try {
    loading.value = true
    const res = await api.get('pages')
    pages.value = res.data?.data ?? res.data
  } catch {
    showAlert('Failed to load pages.', 'error')
  } finally {
    loading.value = false
  }
}

const openCreate = () => {
  form.value   = { id: null, title: '', slug: '', status: 'published' }
  errors.value = {}
  modal.value  = { show: true, mode: 'create' }
}

const openEdit = (page) => {
  form.value   = { id: page.id, title: page.title, slug: page.slug, status: page.status }
  errors.value = {}
  modal.value  = { show: true, mode: 'edit' }
}

const closeModal = () => { modal.value.show = false }

const submitForm = async () => {
  if (!validate()) return
  saving.value = true
  try {
    if (modal.value.mode === 'create') {
      const res = await api.post('pages', form.value)
      pages.value.unshift(res.data?.data ?? res.data)
      showAlert('Page created successfully.')
    } else {
      const res = await api.put(`pages/${form.value.id}`, form.value)
      const updated = res.data?.data ?? res.data
      const idx = pages.value.findIndex(p => p.id === form.value.id)
      if (idx !== -1) pages.value[idx] = { ...pages.value[idx], ...updated }
      showAlert('Page updated successfully.')
    }
    closeModal()
  } catch (e) {
    showAlert(e?.response?.data?.message || 'Something went wrong.', 'error')
  } finally {
    saving.value = false
  }
}

const confirmDelete = (page) => { deleteTarget.value = page }

const deletePage = async () => {
  saving.value = true
  try {
    await api.delete(`pages/${deleteTarget.value.id}`)
    pages.value = pages.value.filter(p => p.id !== deleteTarget.value.id)
    if (expandedId.value === deleteTarget.value.id) expandedId.value = null
    showAlert('Page deleted.')
    deleteTarget.value = null
  } catch {
    showAlert('Failed to delete page.', 'error')
  } finally {
    saving.value = false
  }
}

onMounted(fetchPages)
</script>

